const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = nextInt();
    if (N === null) return;
    const M = nextInt();

    if (M === 0) {
        const ans = new Int32Array(N);
        ans.fill(1);
        process.stdout.write(ans.join(' ') + '\n');
        return;
    }

    const origU = new Int32Array(2 * M);
    const origV = new Int32Array(2 * M);
    const cntV = new Int32Array(N + 2);
    const deg = new Int32Array(N + 2);

    let edgeCount = 0;
    for (let i = 0; i < M; i++) {
        const u = nextInt();
        const v = nextInt();
        origU[edgeCount] = u;
        origV[edgeCount] = v;
        cntV[v]++;
        deg[u]++;
        edgeCount++;

        origU[edgeCount] = v;
        origV[edgeCount] = u;
        cntV[u]++;
        deg[v]++;
        edgeCount++;
    }

    // Radix sort das arestas para que fiquem ordenadas por U, e para o mesmo U por V
    // Passo 1: ordenar por V
    const posV = new Int32Array(N + 2);
    for (let i = 1; i <= N; i++) {
        posV[i] = posV[i - 1] + cntV[i - 1];
    }
    const tempU = new Int32Array(2 * M);
    const tempV = new Int32Array(2 * M);
    for (let i = 0; i < 2 * M; i++) {
        const v = origV[i];
        const idx = posV[v]++;
        tempU[idx] = origU[i];
        tempV[idx] = v;
    }

    // Passo 2: ordenar por U (estável) diretamente na estrutura CSR
    const head = new Int32Array(N + 2);
    for (let i = 1; i <= N; i++) {
        head[i] = head[i - 1] + deg[i - 1];
    }
    const curHead = new Int32Array(head);
    const to = new Int32Array(2 * M);
    for (let i = 0; i < 2 * M; i++) {
        const u = tempU[i];
        const idx = curHead[u]++;
        to[idx] = tempV[i];
    }

    // Nós do DAG:
    // Nós 0 .. 2M - 1: arestas direcionadas v -> w
    // Nós 2M .. 4M - 1: nós de sufixo suf(v, j)
    const totalNodes = 4 * M;
    const child1 = new Int32Array(totalNodes);
    child1.fill(-1);
    const child2 = new Int32Array(totalNodes);
    child2.fill(-1);

    for (let v = 1; v <= N; v++) {
        const d = deg[v];
        const h = head[v];
        for (let j = 0; j < d; j++) {
            const idx = h + j;
            const w = to[idx];

            // Busca binária para achar o menor vizinho de w estritamente maior que v
            let low = head[w];
            let high = head[w] + deg[w] - 1;
            let ans = -1;
            while (low <= high) {
                const mid = (low + high) >> 1;
                if (to[mid] > v) {
                    ans = mid;
                    high = mid - 1;
                } else {
                    low = mid + 1;
                }
            }

            if (ans !== -1) {
                child1[idx] = ans + 2 * M;
            }

            const sufNode = idx + 2 * M;
            child1[sufNode] = idx;
            if (j + 1 < d) {
                child2[sufNode] = idx + 1 + 2 * M;
            }
        }
    }

    // DFS iterativa para calcular os valores no DAG
    const val = new Int32Array(totalNodes);
    const state = new Uint8Array(totalNodes);
    const stack = new Int32Array(totalNodes + 5);

    for (let root = 0; root < totalNodes; root++) {
        if (state[root] !== 0) continue;

        let stackPtr = 0;
        stack[stackPtr++] = root;
        state[root] = 1;

        while (stackPtr > 0) {
            const u = stack[stackPtr - 1];
            const c1 = child1[u];
            const c2 = child2[u];

            let hasUnvisitedChild = false;

            if (c1 !== -1 && state[c1] === 0) {
                state[c1] = 1;
                stack[stackPtr++] = c1;
                hasUnvisitedChild = true;
            }
            if (c2 !== -1 && state[c2] === 0) {
                state[c2] = 1;
                stack[stackPtr++] = c2;
                hasUnvisitedChild = true;
            }

            if (!hasUnvisitedChild) {
                if (u < 2 * M) {
                    if (c1 !== -1) {
                        val[u] = 1 + val[c1];
                    } else {
                        val[u] = 2;
                    }
                } else {
                    const v1 = c1 !== -1 ? val[c1] : 0;
                    const v2 = c2 !== -1 ? val[c2] : 0;
                    val[u] = v1 > v2 ? v1 : v2;
                }
                state[u] = 2;
                stackPtr--;
            }
        }
    }

    const res = new Int32Array(N);
    for (let v = 1; v <= N; v++) {
        if (deg[v] === 0) {
            res[v - 1] = 1;
        } else {
            res[v - 1] = val[head[v] + 2 * M];
        }
    }

    process.stdout.write(res.join(' ') + '\n');
}

solve();
